-- Run after migration, inside BEGIN/ROLLBACK. No persistent users or progress.
begin;
do $test$
declare u uuid:=gen_random_uuid();cid uuid;sid uuid:='2ff86a1c-09d3-40d5-9c44-1f8e2f06b485';cl uuid:='42b44415-64bd-44f9-8472-25d6020d5e33';sn uuid;cn uuid;sn2 uuid;cn2 uuid;sr int;cr int;ship uuid;sk uuid;result jsonb;before_count int;h jsonb;st jsonb;def jsonb;run_id uuid;request_id uuid:=gen_random_uuid();skill_id uuid;eid uuid;
begin
 update public.game_species set hp_per_rank=4 where id=sid;update public.game_classes set hp_per_rank=7 where id=cl;
 select count(*) into before_count from public.characters;
 insert into auth.users(id,email,raw_user_meta_data) values(u,'talent-learning-'||u||'@example.invalid','{}');
 select id into ship from public.game_starter_ships where is_published limit 1;
 select id into sk from public.game_skills where slug='engineering';
 select n.id,t.revision into sn,sr from public.game_talent_tree_nodes n join public.game_talent_trees t on t.id=n.tree_id where t.species_id=sid and n.x=9 and n.min_level=1;
 select n.id,t.revision into cn,cr from public.game_talent_tree_nodes n join public.game_talent_trees t on t.id=n.tree_id where t.class_id=cl and n.x=2 and n.min_level=1;
 select e.to_node_id into sn2 from public.game_talent_tree_edges e where e.from_node_id=sn;
 select e.to_node_id into cn2 from public.game_talent_tree_edges e where e.from_node_id=cn;
 if sn is null or cn is null or sn2 is null or cn2 is null then raise exception 'Missing human/Mercenary content';end if;
 perform set_config('request.jwt.claim.sub',u::text,true);execute 'set local role authenticated';
 begin perform public.create_captain('QA',sid,cl,ship,'{"body":6}',jsonb_build_object(sk::text,6));raise exception 'TEST old creation bypassed choices';exception when raise_exception then if sqlerrm<>'Choose one starting talent in each available tree' then raise;end if;end;
 begin perform public.create_captain_with_talents('QA',sid,cl,ship,'{"body":6}',jsonb_build_object(sk::text,6),cn,sn);raise exception 'TEST wrong scope accepted';exception when raise_exception then if sqlerrm<>'Wrong starting talent tree' then raise;end if;end;
 cid:=public.create_captain_with_talents('QA',sid,cl,ship,'{"body":6}',jsonb_build_object(sk::text,6),sn,cn);
 result:=public.get_player_talent_trees();
 execute 'set local role postgres';def:=private.branch_defenses(sid,cl,cid);if def<>'{"body":5,"mind":4,"soul":2,"morale":4,"social":3}'::jsonb then raise exception 'Incorrect combined starting defenses: %',def;end if;execute 'set local role authenticated';
 if (result->'hp'->>'max_health')::int<>11 then raise exception 'Starting HP must equal 4+7 once';end if;
 if jsonb_array_length(result->'owned')<>2 or result->'points'<>'{"species":0,"class":0,"shared":0}'::jsonb then raise exception 'Incorrect starting allocation: %',result;end if;
 begin perform public.learn_talent_tree_node(sn,sr);raise exception 'TEST duplicate accepted';exception when raise_exception then if sqlerrm<>'Talent already learned' then raise;end if;end;
 begin perform public.learn_talent_tree_node(sn2,sr);raise exception 'TEST level gate bypassed';exception when raise_exception then if sqlerrm<>'Talent prerequisites unmet' then raise;end if;end;
 execute 'set local role postgres';update public.character_progress set level=2 where character_id=cid;if (private.combat_hero(cid)->>'max_health')::int<>11 then raise exception 'Unspent point changed HP';end if;execute 'set local role authenticated';
 begin perform public.learn_talent_tree_node(sn2,sr-1);raise exception 'TEST stale accepted';exception when serialization_failure then null;end;
 result:=public.learn_talent_tree_node(sn2,sr);
 execute 'set local role postgres';if private.branch_defenses(sid,cl,cid)<>'{"body":7,"mind":5,"soul":3,"morale":5,"social":4}'::jsonb then raise exception 'Species defense growth wrong';end if;execute 'set local role authenticated';
 if (result->'hp'->>'max_health')::int<>15 then raise exception 'Species point should add exactly 4 HP';end if;
 if (result->'points'->>'shared')::int<>0 then raise exception 'Level 2 point not consumed';end if;
 begin perform public.learn_talent_tree_node(cn2,cr);raise exception 'TEST overspend accepted';exception when raise_exception then if sqlerrm<>'No talent points available' then raise;end if;end;
 execute 'set local role postgres';update public.character_progress set level=3 where character_id=cid;execute 'set local role authenticated';
 result:=public.learn_talent_tree_node(cn2,cr);
 execute 'set local role postgres';if private.branch_defenses(sid,cl,cid)<>'{"body":8,"mind":6,"soul":4,"morale":7,"social":5}'::jsonb then raise exception 'Class defense growth wrong';end if;execute 'set local role authenticated';
 if (result->'hp'->>'max_health')::int<>22 then raise exception 'Class point should add exactly 7 HP';end if;
 if jsonb_array_length(result->'owned')<>4 or (result->'points'->>'shared')::int<>0 then raise exception 'Level 3 either-tree spend failed';end if;
 begin insert into public.character_tree_nodes(character_id,node_id,tree_id,branch,snapshot) select cid,gen_random_uuid(),id,'species','{}' from public.game_talent_trees limit 1;raise exception 'TEST direct write accepted';exception when insufficient_privilege then null;end;
 execute 'set local role postgres';
 if (private.combat_hero(cid)->>'max_health')::int<>22 then raise exception 'Combat snapshot HP mismatch';end if;
 update public.character_combat_progress set health=3,class_rank=2 where character_id=cid;update public.character_progress set level=4 where character_id=cid;
 if (private.combat_hero(cid)->>'max_health')::int<>29 or (private.combat_hero(cid)->>'health')::int<>3 then raise exception 'Legacy branch HP or wounded health mismatch';end if;
 if private.tree_skill_bonus(cid,sk,'mind')<>2 then raise exception 'Engineering passive not active';end if;
 if jsonb_array_length(private.combat_hero(cid)->'powers')<2 then raise exception 'Learned powers missing';end if;
 if (select count(*) from public.character_powers where character_id=cid)<>2 then raise exception 'Power rewards not persisted';end if;
 if (select count(*) from public.characters)<>before_count+1 then raise exception 'Failed creation left partial character';end if;

 if to_regclass('public.game_combat_profiles') is not null then raise exception 'Profiles still exist';end if;
 if (select count(*) from public.game_talent_tree_nodes where kind='passive' and talent_id is not null and effects='[]')<>(select count(*) from public.game_talent_tree_nodes where kind='passive') then raise exception 'Inline passives remain';end if;
 if (select count(*) from public.game_skills where is_active_defense)<>5 then raise exception 'Missing active defenses';end if;
 h:=private.combat_hero(cid);
 if jsonb_array_length(h->'active_defense_skills')<>5 then raise exception 'Combat hero missing defensive skills';end if;
 select id into eid from public.game_enemies where is_published limit 1;
 st:=private.combat_initial(h,private.combat_enemy(eid)||jsonb_build_object('powers','[]'::jsonb,'health',10000,'max_health',10000),'{}');
 insert into public.combat_runs(character_id,owner_id,simulation,state) values(cid,u,false,st) returning id into run_id;
 skill_id:=(h->'active_defense_skills'->0->>'id')::uuid;
 execute 'set local role authenticated';
 result:=public.activate_combat_defense(run_id,0,request_id,skill_id);
 if (result->'state'->'actors'->0->>'action_points')::int<>2 or result->'state'->'actors'->0->'active_defense'->>'id'<>skill_id::text then raise exception 'Activation cost or selection wrong';end if;
 if public.activate_combat_defense(run_id,0,request_id,skill_id)<>result then raise exception 'Activation retry not idempotent';end if;
 begin perform public.activate_combat_defense(run_id,0,gen_random_uuid(),skill_id);raise exception 'TEST stale activation accepted';exception when raise_exception then if sqlerrm<>'Combat state changed; reload' then raise;end if;end;
 result:=public.combat_action(run_id,(result->>'revision')::int,gen_random_uuid(),null,1);
 if (result->'state'->'actors'->0->>'action_points')::int<>3 or result->'state'->'actors'->0->'active_defense'<>'null'::jsonb then raise exception 'Defense expiry / AP reset wrong';end if;
 execute 'set local role postgres';
 perform set_config('request.jwt.claim.sub',gen_random_uuid()::text,true);execute 'set local role authenticated';
 if exists(select 1 from public.character_tree_nodes where character_id=cid) then raise exception 'Other user reads choices';end if;
 begin perform public.learn_talent_tree_node(sn,sr);raise exception 'TEST foreign character accepted';exception when raise_exception then if sqlerrm<>'Create a captain first' then raise;end if;end;
 execute 'set local role postgres';
 if has_function_privilege('anon','public.learn_talent_tree_node(uuid,integer)','execute') or has_function_privilege('authenticated','private.create_captain_impl(text,uuid,uuid,uuid,jsonb,jsonb)','execute') then raise exception 'Unsafe grants';end if;
end $test$;
rollback;
